(* [comment removed for export] *)
Definition OUT_sn2b (cap : Z) (bs : list Z) : M sn2 unit :=
  st <- mget ;; let '(d, o) := st in
  if zlength d + zlength o + zlength bs <=? cap
  then (if zlength o + zlength bs <=? SN_CAP then mput (d, o ++ bs) else mput (d ++ o ++ bs, []))
  else munr.

