Lemma conv_int_sn2b : forall cnt fl w p xp argi prefix body (k : Z -> M sn2 Z) st ps r,
  int_pieces cnt fl w p xp argi prefix body = Some (ps, r) -> zlength (sn2_flat st) + zlength (concat ps) <= cap ->
