Theorem printf_model_sn2b_pushes : forall fmt args ps r,
  printf_pieces fmt args = Some (ps, r) -> zlength (concat ps) <= cap ->
  printf_model (OUT_sn2b cap) OUTFP_sn2 fmt args ([], []) = ITree.Ret (Ok (r, sn2_pushes ([], []) ps)).
Proof.
